import type { AutoMovieHumanLoftFrame } from "../lofting/AutoMovieHumanLoftFrame";
import type { AutoMovieHumanLoftParameter } from "../lofting/AutoMovieHumanLoftParameter";
import type { IAutoMovieHumanRelief } from "./IAutoMovieHumanRelief";

/**
 * A chain stored as its key sections only.
 *
 * Keys sit at shape events (a ring shared with another chain, a silhouette
 * or feature change), and every section between them is generated by
 * {@link AutoMovieHumanFeatureChain.expand}: the natural cubic spline through
 * the keys, the interpolant of least bending energy, so the skin between two
 * keys is smooth by construction. Transforming a key moves every section it
 * governs.
 */
export interface IAutoMovieHumanFeatureChain {
  /** Name of the chain it generates; unique across the calibration. */
  name: string;

  /** Number of periodic B-spline control points of every section, N. */
  order: number;

  /** Phase correspondence rule of the generated chain. */
  rule: AutoMovieHumanLoftParameter.Rule;

  /** Number of uniform phases of the generated chain's own rings. */
  samples: number;

  /** Key sections by strictly increasing station, at least two. */
  keys: IAutoMovieHumanFeatureChain.IKey[];

  /** Reliefs over the chain's surface; absent means none. */
  reliefs?: IAutoMovieHumanRelief[];
}
export namespace IAutoMovieHumanFeatureChain {
  /** One key section. */
  export interface IKey {
    /**
     * Station of the section along the chain, mm; the world height of a
     * horizontal one.
     */
    station: number;

    /**
     * Section plane; absent means horizontal at the station. Between keys
     * the plane moves as `AutoMovieHumanLoftChain.frame` interpolates it.
     */
    frame?: AutoMovieHumanLoftFrame.IFrame;

    /**
     * Control points `[x_0 .. x_{N-1}, z_0 .. z_{N-1}]` in the section plane,
     * mm, the layout of `AutoMovieHumanSplineCurve`.
     */
    coefficients: number[];
  }
}
